contracts/FibraManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./LadrilloBrick.sol";

contract FibraManager is ERC20, Ownable {

    struct Fibra {
        string name;
        address[] brickTokens; // Ladrillos ERC-20 agrupados en esta FIBRA
        bool isActive;
        uint256 totalSupply;
    }

    // ID de Fibra => Detalle de la FIBRA
    mapping(uint256 => Fibra) public fibras;
    uint256 public fibraCounter;

    event FibraCreated(uint256 indexed fibraId, string name, address[] brickTokens);
    event FibraDividendReceived(uint256 indexed fibraId, uint256 totalAmount);

    constructor() ERC20("Propiedad Digital FIBRA", "PDFIBRA") Ownable(msg.sender) {}

    /**
     * @notice Agrupa múltiples tokens LadrilloBrick para crear un portafolio de inversión (FIBRA).
     * @dev El creador recibe tokens de la FIBRA que representan su participación en el portafolio.
     */
    function createFibra(string memory _name, address[] memory _brickTokens, uint256 _initialSupply) external onlyOwner {
        require(_brickTokens.length > 0, "Debe incluir al menos un token Ladrillo");

        uint256 newFibraId = fibraCounter;
        fibras[newFibraId] = Fibra({
            name: _name,
            brickTokens: _brickTokens,
            isActive: true,
            totalSupply: _initialSupply
        });

        fibraCounter++;

        // Mintear tokens de la FIBRA al owner (representando el portafolio)
        _mint(msg.sender, _initialSupply * 10 ** decimals());

        emit FibraCreated(newFibraId, _name, _brickTokens);
    }

    /**
     * @notice Recibe AVAX de rentas del portafolio entero y lo distribuye equitativamente 
     * entre todos los LadrilloBricks que componen la FIBRA.
     */
    function distributeFibraDividends(uint256 _fibraId) external payable {
        Fibra storage fibra = fibras[_fibraId];
        require(fibra.isActive, "La FIBRA no existe o esta inactiva");
        require(msg.value > 0, "Monto de dividendos debe ser mayor a cero");

        uint256 numBricks = fibra.brickTokens.length;
        uint256 amountPerBrick = msg.value / numBricks; // División equitativa entre inmuebles del fondo

        for (uint256 i = 0; i < numBricks; i++) {
            address brickContract = fibra.brickTokens[i];

            // Invocamos la función release de cada Ladrillo enviando su porción de AVAX
            LadrilloBrick(payable(brickContract)).release{value: amountPerBrick}();
        }

        emit FibraDividendReceived(_fibraId, msg.value);
    }
}

contracts/interfaces/IIcmMessenger.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IIcmMessenger
 * @notice Interfaz para la mensajería nativa de Avalanche (Interchain Messaging)
 * @dev Esta interfaz permitirá a la L1 propia comunicarse con la C-Chain de Fuji.
 */
interface IIcmMessenger {

    /**
     * @notice Envía un mensaje a otra subred.
     * @param destinationBlockchainID El ID de la blockchain de destino (e.g. Fuji C-Chain).
     * @param destinationAddress La dirección del contrato receptor en la cadena de destino.
     * @param message El payload del mensaje codificado en bytes.
     */
    function sendInterchainMessage(
        bytes32 destinationBlockchainID,
        address destinationAddress,
        bytes calldata message
    ) external returns (uint256 messageNonce);

    /**
     * @notice Recibe y procesa un mensaje proveniente de otra subred.
     * @dev Esta función suele ser llamada por el contrato de mensajería del sistema.
     * @param sourceBlockchainID ID de la blockchain de origen.
     * @param sourceAddress Dirección del contrato emisor.
     * @param message Payload del mensaje.
     */
    function receiveInterchainMessage(
        bytes32 sourceBlockchainID,
        address sourceAddress,
        bytes calldata message
    ) external;

    event InterchainMessageSent(
        bytes32 indexed destinationBlockchainID,
        address indexed destinationAddress,
        uint256 nonce,
        bytes message
    ) ;

    event InterchainMessageReceived(
        bytes32 indexed sourceBlockchainID,
        address indexed sourceAddress,
        bytes message
    );
}

contracts/LadrilloBrick.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract LadrilloBrick is ERC20, Ownable, ReentrancyGuard {

    // Dirección del contrato NFT que representa las propiedades
    address public immutable propertyNFTContract;
    // ID del inmueble específico en el contrato ERC-721
    uint256 public immutable propertyId;

    // Listado de holders para la distribución de dividendos (simplificado para hackathon)
    address[] private _holders;
    mapping(address => bool) private _isHolder;

    event DividendDistributed(uint256 amount, uint256 holdersCount);

    constructor(
        string memory name, 
        string memory symbol, 
        address _nftContract, 
        uint256 _propertyId,
        uint256 _initialSupply,
        address _initialOwner
    ) 
        ERC20(name, symbol) 
        Ownable(_initialOwner) 
    {
        require(_nftContract != address(0), "Direccion de NFT invalida");
        propertyNFTContract = _nftContract;
        propertyId = _propertyId;

        // Mintear el supply inicial (fracciones) al creador/dueño original
        _mint(_initialOwner, _initialSupply * 10 ** decimals());
    }

    /**
     * @notice Distribuye dividendos (rentas en AVAX) a los holders proporcionalmente.
     * @dev Implementa el requerimiento de release() vía push payment.
     */
    function release() external payable nonReentrant {
        uint256 totalDividend = msg.value;
        require(totalDividend > 0, "El dividendo debe ser mayor a 0");
        uint256 totalTokens = totalSupply();
        require(totalTokens > 0, "No hay tokens emitidos");

        uint256 distributedCount = 0;

        for (uint256 i = 0; i < _holders.length; i++) {
            address holder = _holders[i];
            uint256 balance = balanceOf(holder);

            if (balance > 0) {
                // Cálculo proporcional: (Balance * Dividendo Total) / Total Supply
                uint256 share = (balance * totalDividend) / totalTokens;
                if (share > 0) {
                    (bool success, ) = payable(holder).call{value: share}("");
                    if (success) {
                        distributedCount++;
                    }
                }
            }
        }

        emit DividendDistributed(totalDividend, distributedCount);
    }

    // Sobrescribir transferencia para llevar registro de los holders activos
    function _update(address from, address to, uint256 value) internal override {
        super._update(from, to, value);

        if (to != address(0) && balanceOf(to) > 0 && !_isHolder[to]) {
            _isHolder[to] = true;
            _holders.push(to);
        }
        // Nota: En este nivel de hackathon, no eliminamos de _holders para evitar 
        // operaciones de borrado costosas, simplemente validamos balance > 0 en release()
    }

    // Permitir recibir fondos de rentas directamente
    receive() external payable {
        // Ejecuta la distribución automáticamente si entra AVAX directamente al contrato
        if(msg.value > 0) {
            this.release{value: msg.value}();
        }
    }
}

